def main():
    deps = {'wall': [], 'gate': ['wall'], 'foundation': [], 'street': ['foundation'], 'plaza': ['street', 'gate']}
    order = ['wall', 'foundation', 'gate', 'street', 'plaza']
    ok = True
    for asset, ds in deps.items():
        for d in ds:
            if order.index(d) > order.index(asset):
                ok = False
    print(f'build order: {order}')
    print(f'order respects dependencies: {ok}')
    print(f'assets: {len(order)}')
    print('cycles: none detected')

main()

